"""Controller controller -- generated by plugin_authoring. See context.md for this plugin's iteration history."""

from __future__ import annotations

import json
import os
import threading
import udi_interface

LOGGER = udi_interface.LOGGER


class Controller(udi_interface.Node):
    id = 'controller'
    drivers = [{'driver': 'ST', 'value': 0, 'uom': 25, 'name': 'Status'}]
    def __init__(self, polyglot, primary='ctl', address='ctl', name='ProfileSizeTest Controller'):
        super().__init__(polyglot, primary, address, name)
        self.poly = polyglot
        self.persist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "persist")
        os.makedirs(self.persist_dir, exist_ok=True)
        # Synchronization for __start()'s wait-for-configDone gate (see __configDoneHandler).
        self.configDone = threading.Condition()
        self.configDoneAlready = False
        self.Parameters = udi_interface.Custom(self.poly, 'customparams')
        self.poly.setCustomParamsDoc("<h2>Profile Size Test - configuration</h2>\n<p>This plugin sends <b>synthetic dynamic profiles</b> of increasing size to PG3 with <code>updateJsonProfile</code> and reports which sizes were accepted and which failed. The full ASCII report is written to this plugin's log (Log &rarr; Real Time Log / Download Log). The <b>Test Results</b> child node shows the summary (Result, Smallest Failure, Largest Pass, Last Run).</p>\n<p><b>Warning:</b> every test pushes extra <code>NODE_nnn</code> nodedefs and <code>*_n</code> editors into this plugin's profile. Use a test system. A rejected or oversized profile may leave the Admin Console with unresolved labels or blank node panels.</p>\n<h3>Parameters</h3>\n<table>\n<tr><th>Key</th><th>Default</th><th>Meaning</th></tr>\n<tr><td><code>mode</code></td><td>sweep</td><td><code>sweep</code> = step from <code>sweep_start</code> to <code>sweep_end</code> KB. <code>test</code> = send one small and one large payload (<code>small_kb</code>, <code>large_kb</code>). <code>file</code> = send the JSON file named in <code>profile_file</code>.</td></tr>\n<tr><td><code>sweep_start</code></td><td>20</td><td>First payload size in KB (sweep mode).</td></tr>\n<tr><td><code>sweep_end</code></td><td>100</td><td>Last payload size in KB, inclusive (sweep mode). Maximum 2048.</td></tr>\n<tr><td><code>sweep_step</code></td><td>10</td><td>Increment in KB between payloads (sweep mode).</td></tr>\n<tr><td><code>small_kb</code></td><td>15</td><td>Size of the small payload (test mode).</td></tr>\n<tr><td><code>large_kb</code></td><td>90</td><td>Size of the large payload (test mode).</td></tr>\n<tr><td><code>profile_file</code></td><td>(empty)</td><td>Path to an exported profile JSON containing top-level <code>editors</code> and <code>nodedefs</code>. A relative path is resolved inside this plugin's <code>persist/</code> folder. Only used when <code>mode</code> is <code>file</code>.</td></tr>\n<tr><td><code>include_st</code></td><td>true</td><td>When <code>true</code>, each synthetic nodedef gets a valid <code>ST</code> property. Set <code>false</code> to reproduce the original generator output exactly (nodedefs without <code>ST</code>); note that a failure in that case may be caused by the profile's structure rather than its size.</td></tr>\n<tr><td><code>run_on_start</code></td><td>false</td><td>When <code>true</code>, the test runs automatically each time the plugin starts. When <code>false</code> it waits for a command or a configuration change.</td></tr>\n</table>\n<h3>Running a test</h3>\n<ul>\n<li>Change and save any parameter above (after the plugin has started): the test re-runs with the new values.</li>\n<li>Or use the Controller node's commands in the Admin Console: <b>Run Size Sweep</b> and <b>Run Two-Tier Test</b>.</li>\n</ul>\n<p>Invalid values are replaced by their defaults and a notice is shown on this page.</p>")
        # Additional node classes (results_node, profile_size_engine) -- construct and self.poly.addNode() them from discover()/start() once their real addresses/names are known (run candidate names/addresses through self.poly.getValidName()/getValidAddress() first).
        self.poly.subscribe(self.poly.START, self.__start, address)
        self.poly.subscribe(self.poly.STOP, self.__stop)
        self.poly.subscribe(self.poly.POLL, self.__poll)
        self.poly.subscribe(self.poly.CONFIG, self.__configHandler)
        self.poly.subscribe(self.poly.CONFIGDONE, self.__configDoneHandler)
        self.poly.subscribe(self.poly.CUSTOMPARAMS, self.parameterHandler)
        self.poly.subscribe(self.poly.CUSTOMNS, self.__customNSHandler)
        self.poly.subscribe(self.poly.CUSTOMDATA, self.__customDataHandler)
        self.poly.subscribe(self.poly.ADDNODEDONE, self.__addNodeDoneHandler)
        self.poly.subscribe(self.poly.DELNODEDONE, self.__removeNodeDoneHandler)
        self.poly.subscribe(self.poly.DISCOVER, self.discover)
        self.poly.subscribe(self.poly.BONJOUR, self.__bonjourHandler)
        self.poly.addNode(self, conn_status='ST')

    def __start(self):
        LOGGER.info("%s: start", self.name)
        try:
            if not self.configDoneAlready:
                with self.configDone:
                    if not self.configDone.wait(timeout=10):
                        LOGGER.error("%s: timed out waiting for configDone", self.name)
                        return
            self.start()
        except Exception as ex:
            LOGGER.error("%s: start failed: %s", self.name, ex)

    def __stop(self):
        LOGGER.info("%s: stop", self.name)
        self.stop()

    def __poll(self, polltype):
        if polltype == "shortPoll":
            self.shortPoll()
        elif polltype == "longPoll":
            self.longPoll()

    def __configHandler(self, config):
        self.processConfig(config)

    def __configDoneHandler(self):
        LOGGER.info("%s: config done", self.name)
        with self.configDone:
            self.configDoneAlready = True
            self.configDone.notifyAll()

    def __addNodeDoneHandler(self, data):
        LOGGER.debug("%s: add node done: %s", self.name, data)

    def __removeNodeDoneHandler(self, data):
        LOGGER.debug("%s: remove node done: %s", self.name, data)

    def __customNSHandler(self, key, data):
        self.customParamHandler(key, data)

    def __customDataHandler(self, data):
        LOGGER.debug("%s: custom data: %s", self.name, data)

    def __bonjourHandler(self, response):
        LOGGER.debug("%s: bonjour: %s", self.name, response)

    # --- developer-authored overrides (edit freely; regeneration preserves them) ---

    def start(self):
        import time
        import udi_interface
        LOGGER = udi_interface.LOGGER
        from profile_size_engine import make_engine, parse_params
        from results_node import ResultsNode
        poly = self.poly

        # Child node that carries the result readouts (the Controller itself only has ST).
        node = ResultsNode(poly, self.address,
                           poly.getValidAddress('results'),
                           poly.getValidName('Test Results'))
        poly.addNode(node)
        self._pst_node = node

        def updater(payload):
            res = poly.updateJsonProfile(payload, {"waitResponse": True})
            if res is False:
                raise RuntimeError("updateJsonProfile returned False")
            if isinstance(res, dict) and (res.get('error') or res.get('success') is False):
                raise RuntimeError(res.get('message', 'Profile update rejected by Polyglot'))

        def log(msg):
            LOGGER.info(msg)

        def on_done(summary, results):
            node.setDriver('ST', summary['code'])
            node.setDriver('MIN_FAIL_KB', summary['min_fail_kb'])
            node.setDriver('MAX_PASS_KB', summary['max_pass_kb'])
            node.setDriver('TIME', int(time.time()))

        base_dir = getattr(self, 'persist_dir', '.')
        self._pst_engine = make_engine(updater, log, on_done=on_done, base_dir=base_dir)
        params = getattr(self, '_pst_params', None)
        if params is None:
            params, _warnings = parse_params({})
            self._pst_params = params
        self._pst_started = True
        if params.get('run_on_start'):
            LOGGER.info('run_on_start is true; starting profile size test')
            self._pst_engine.start_async(params)
        else:
            LOGGER.info('ProfileSizeTest ready. Use the Run Size Sweep / Run Two-Tier Test commands, or save a config change, to start a test.')

    def stop(self, *args, **kwargs):
        pass

    def discover(self, *args, **kwargs):
        pass

    def shortPoll(self, *args, **kwargs):
        pass

    def longPoll(self, *args, **kwargs):
        pass

    def processConfig(self, *args, **kwargs):
        pass

    def parameterHandler(self, params):
        import udi_interface
        LOGGER = udi_interface.LOGGER
        from profile_size_engine import DEFAULT_PARAMS, parse_params
        raw = dict(params) if params else {}
        self.Parameters.load(raw)
        for key, default_val in DEFAULT_PARAMS.items():
            if key not in self.Parameters:
                if isinstance(default_val, bool):
                    self.Parameters[key] = 'true' if default_val else 'false'
                else:
                    self.Parameters[key] = str(default_val)
        parsed, warnings = parse_params(raw)
        changed = parsed != getattr(self, '_pst_params', None)
        self._pst_params = parsed
        try:
            if warnings:
                self.poly.Notices['pst_params'] = '; '.join(warnings)
            else:
                self.poly.Notices.delete('pst_params')
        except Exception as e:
            LOGGER.warning('Could not update parameter notice: %s' % e)
        engine = getattr(self, '_pst_engine', None)
        if changed and getattr(self, '_pst_started', False) and engine is not None:
            LOGGER.info('Custom parameters changed; re-running profile size test with %s' % parsed)
            engine.start_async(parsed)
        else:
            LOGGER.info('Custom parameters stored: %s' % parsed)

    def customParamHandler(self, *args, **kwargs):
        pass

    def run_sweep(self, *args, **kwargs):
        import udi_interface
        engine = getattr(self, '_pst_engine', None)
        if engine is None:
            udi_interface.LOGGER.warning('Run Size Sweep ignored: plugin has not finished starting')
            return
        params = dict(getattr(self, '_pst_params', None) or {})
        params['mode'] = 'sweep'
        udi_interface.LOGGER.info('Command: Run Size Sweep')
        engine.start_async(params)

    def run_twotier(self, *args, **kwargs):
        import udi_interface
        engine = getattr(self, '_pst_engine', None)
        if engine is None:
            udi_interface.LOGGER.warning('Run Two-Tier Test ignored: plugin has not finished starting')
            return
        params = dict(getattr(self, '_pst_params', None) or {})
        params['mode'] = 'test'
        udi_interface.LOGGER.info('Command: Run Two-Tier Test')
        engine.start_async(params)

    # --- command dispatch (profile cmds.accepts; see udi_interface.Node.runCmd) ---
    commands = {'RUN_SWEEP': run_sweep, 'RUN_TWOTIER': run_twotier}
